create or replace TABLE KFL_PRODUCTION.DBP_MSI_DATA.KAMPAGNE_VORLAGE_MO_SUM_2 (
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant_2 im DWH.',
	KAMPAGNE_ID VARCHAR(100) NOT NULL COMMENT 'Eindeutige Kennung der Kampagne_2, die der GUID im Quellsystem entspricht.',
	KJMO NUMBER(38,0) NOT NULL COMMENT 'Kombinierter Schlüssel aus Kalenderjahr und Monat_2, formatiert als YYYYMM.',
	NACHRICHT_VORLAGE_ID VARCHAR(100) NOT NULL COMMENT 'Vom Quellsystem generierte ID der Nachrichtenvorlage (GUID).',
	KOMMUNIKATIONSKANAL_ID NUMBER(38,0) NOT NULL COMMENT 'Kennung des Kommunikationskanals, für den die Nachrichtenvorlage bestimmt ist, z. B. E-Mail, Push-Benachrichtigung, SMS, etc.',
	NACHRICHT_SUBVORLAGE_NAME_LISTE_TXT VARCHAR(4000) NOT NULL COMMENT 'Enthält die Reihenfolge und Namen zu den IDs der verwendeten E-Mail-Subvorlagevarianten, z. B. für \"2-null-2-3\" in nachricht_subvorlage_id_liste_txt könnte hier stehen \"Obst-default-Obst-Gemüse\".',
	KAMPAGNE_NAME VARCHAR(200) NOT NULL COMMENT 'Bezeichnender Name der Kampagnendefinition.',
	DAT_KAMPAGNE_VON DATE COMMENT 'Datum, an dem die Kampagne_2 startet wird.',
	KAMPAGNE_RHYTHMUS_TYP_ID NUMBER(38,0) NOT NULL COMMENT 'Numerischer Code zur Kennzeichnung der Wiederholungshäufigkeit der Kampagne_2, z. B. 0 = Recurring, 1 = Ongoing, 2 = OneTime, 3 = Event.',
	KAMPAGNE_VERSION_NR NUMBER(38,0) NOT NULL COMMENT 'Version der Kampagne. Bei jedem Auslösen einer Kampagne_2 wird eine_2 neue Version erstellt. Diese Zahl entspricht der genutzen Version.',
	NACHRICHT_VORLAGE_TITEL_TXT VARCHAR(4000) COMMENT 'Titel der Nachrichtenvorlage, z. B. Betreff einer E-Mail. Gilt nur für E-Mail und Push-Benachrichtigung.',
	NACHRICHT_VORLAGE_TXT VARCHAR(4000) COMMENT 'Text der Nachrichtenvorlage. Es handelt sich um die Vorschau für E-Mails und die Nachricht für Push-Benachrichtigungen und SMS.',
	NACHRICHT_VORLAGE_URL_TXT VARCHAR(2000) COMMENT 'In-App-Navigation Link-URL, die in der Nachrichtenvorlage enthalten sein soll. Sie wird nur für Push-Benachrichtigungen befüllt.',
	NACHRICHT_VORLAGE_BILD_ID VARCHAR(100) COMMENT 'Kennung des Bildes, das in der Nachrichtenvorlage verwendet werden soll. Sie wird nur für Push-Benachrichtigungen befüllt.',
	ANZ_KAMPAGNE_KUNDE_GESAMT NUMBER(38,0) NOT NULL COMMENT 'Zielgruppengröße, die über die Kampagne_2 informiert wird. Die Zahle bezieht sich auf Ebene der Kampagne_ID und Monat.',
	ANZ_KUNDE_GESENDET NUMBER(38,0) NOT NULL COMMENT 'Anzahl der Kunden, an die eine_2 Nachricht gesendet wurde.',
	RATE_KUNDE_GESENDET NUMBER(38,5) NOT NULL COMMENT 'Prozentualer Anteil der Nachricht, an die eine_2 Nachricht gesendet wurde, an der Gesamtzahl der Kunden innerhalb der Kampagne. (Berechnung: anz_kunde_gesendet / anz_kampagne_kunde_gesamt)',
	ANZ_KUNDE_BLOCKIERT NUMBER(38,0) NOT NULL COMMENT 'Anzahl der Kunden, an die eine_2 Nachricht blockiert wurde.',
	RATE_KUNDE_BLOCKIERT NUMBER(38,5) NOT NULL COMMENT 'Prozentualer Anteil der Kunden, an die eine_2 Nachricht blockiert wurde, an der Gesamtzahl der Kunden, an die eine_2 Nachricht gesendet wurde. (Berechnung: anz_kunde_blockiert / anz_kunde_gesendet)',
	ANZ_KUNDE_ZUGESTELLT NUMBER(38,0) NOT NULL COMMENT 'Anzahl der Kunden, an die eine_2 Nachricht zugestellt wurde.',
	RATE_KUNDE_ZUGESTELLT NUMBER(38,5) NOT NULL COMMENT 'Prozentualer Anteil der Kunden, an die eine_2 Nachricht zugestellt wurde, an der Gesamtzahl der Kunden, an die eine_2 Nachricht gesendet wurde. (Berechnung: anz_kunde_zugestellt / anz_kunde_gesendet)',
	ANZ_KUNDE_BOUNCED_SOFT NUMBER(38,0) NOT NULL COMMENT 'Anzahl der Kunden, bei denen eine_2 Nachricht aufgrund eines Soft Bounces nicht zugestellt werden konnte.',
	RATE_KUNDE_BOUNCED_SOFT NUMBER(38,5) NOT NULL COMMENT 'Prozentualer Anteil der Kunden, bei denen eine_2 Nachricht aufgrund eines Soft Bounces nicht zugestellt werden konnte, an der Gesamtzahl der Kunden, an die eine_2 Nachricht gesendet wurde. (Berechnung: anz_kunde_bounced_soft / anz_kunde_gesendet)',
	ANZ_KUNDE_BOUNCED_HARD NUMBER(38,0) NOT NULL COMMENT 'Anzahl der Kunden, bei denen eine_2 Nachricht aufgrund eines Hard Bounces nicht zugestellt werden konnte.',
	RATE_KUNDE_BOUNCED_HARD NUMBER(38,5) NOT NULL COMMENT 'Prozentualer Anteil der Kunden, bei denen eine_2 Nachricht aufgrund eines Soft Bounces nicht zugestellt werden konnte, an der Gesamtzahl der Kunden, an die eine_2 Nachricht gesendet wurde. (Berechnung: anz_kunde_bounced_hard / anz_kunde_gesendet)',
	ANZ_KUNDE_GEOEFFNET NUMBER(38,0) NOT NULL COMMENT 'Anzahl der Kunden, die eine_2 Nachricht geöffnet hat.',
	RATE_KUNDE_GEOEFFNET_ZUGESTELLT NUMBER(38,5) NOT NULL COMMENT 'Prozentualer Anteil der Kunden, die eine_2 Nachricht geöffnet hat, an der Gesamtzahl der Kunden, an die eine_2 Nachricht zugestellt wurde. (Berechnung: anz_kunde_geoeffnet / anz_kunde_zugestellt)',
	ANZ_KUNDE_GEKLICKT NUMBER(38,0) NOT NULL COMMENT 'Anzahl der Kunden, die auf mindestens einen Link in einer Nachricht geklickt hat.',
	RATE_KUNDE_GEKLICKT_GESENDET NUMBER(38,5) NOT NULL COMMENT 'Prozentualer Anteil der Kunden, die auf mindestens einen Link in einer Nachricht geklickt hat, an der Gesamtzahl der Kunden, an die eine_2 Nachricht gesendet wurde. (Berechnung: anz_kunde_geklickt / anz_kunde_gesendet)',
	RATE_KUNDE_GEKLICKT_GEOEFFNET NUMBER(38,5) NOT NULL COMMENT 'Prozentualer Anteil der Kunden, die auf mindestens einen Link in einer Nachricht geklickt hat, an der Gesamtzahl der Kunden, die eine_2 Nachricht geöffnet hat. (Berechnung: anz_kunde_geklickt / anz_kunde_geoeffnet)',
	RATE_KUNDE_GEKLICKT_ZUGESTELLT NUMBER(38,5) NOT NULL COMMENT 'Prozentualer Anteil der Kunden, die auf mindestens einen Link in einer Nachricht geklickt hat, an der Gesamtzahl der Kunden, an die eine_2 Nachricht zugestellt wurde. (Berechnung: anz_kunde_geklickt / anz_kunde_zugestellt)',
	ANZ_KUNDE_SPAM NUMBER(38,0) NOT NULL COMMENT 'Anzahl der Kunden, bei denen eine_2 Nachricht als Spam klassifiziert wurde.',
	RATE_KUNDE_SPAM NUMBER(38,5) NOT NULL COMMENT 'Prozentualer Anteil der Kunden, bei denen eine_2 Nachricht als Spam klassifiziert wurde, an der Gesamtzahl der Kunden, an die eine_2 Nachricht gesendet wurde. (Berechnung: anz_kunde_spam / anz_kunde_gesendet)',
	ANZ_KUNDE_ABGEMELDET NUMBER(38,0) NOT NULL COMMENT 'Anzahl der Kunden, die sich abgemeldet haben.',
	RATE_KUNDE_ABGEMELDET NUMBER(38,5) NOT NULL COMMENT 'Prozentualer Anteil der Kunden, die sich abgemeldet haben, an der Gesamtzahl der Kunden, an die eine_2 Nachricht gesendet wurde. (Berechnung: anz_kunde_abgemeldet / anz_kunde_gesendet)',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	constraint PK_KAMPAGNE_VORLAGE_MO_SUM primary key (MANDANT_ID, KAMPAGNE_ID, KJMO, NACHRICHT_VORLAGE_ID, KOMMUNIKATIONSKANAL_ID, NACHRICHT_SUBVORLAGE_NAME_LISTE_TXT)
)COMMENT='Die Tabelle enthält monatlich aggregierte Daten zu den Kampagnen. Sie wird zur Erstellung von Monatsberichten verwendet und beinhaltet Kennzahlen wie die Gesamtzahl der versendeten Nachrichten, die Öffnungsraten, die Klickraten und weitere relevante Metriken pro Kampagne_2, Monat_2, Vorlage und Subvorlage_name_liste.'
;